{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "/ds_salaries.csv"
  },
  "transform": [
    {
      "calculate": "datum.company_location == 'US' ? '美国' : '其他国家'",
      "as": "US_vs_ROW"
    },
    {
      "calculate": "{'EN': '入门级', 'MI': '中级', 'SE': '高级', 'EX': '专家级'}[datum.experience_level]",
      "as": "experience_level_cn"
    },
    {
      "calculate": "{'S': '小型', 'M': '中型', 'L': '大型'}[datum.company_size]",
      "as": "company_size_cn"
    }
  ],
  "vconcat": [
    {
      "hconcat": [
        {
          "width": 400,
          "height": 300,
          "title": "全球数据科学平均年薪Top 10 (USD)",
          "layer": [
            {
              "mark": "bar",
              "transform": [
                {
                  "aggregate": [{"op": "mean", "field": "salary_in_usd", "as": "mean_salary"}],
                  "groupby": ["company_location"]
                },
                {
                  "window": [{"op": "rank", "as": "rank"}],
                  "sort": [{"field": "mean_salary", "order": "descending"}]
                },
                {"filter": "datum.rank <= 10"}
              ],
              "encoding": {
                "x": {
                  "field": "mean_salary",
                  "type": "quantitative",
                  "title": "平均年薪 (美元)"
                },
                "y": {
                  "field": "company_location",
                  "type": "nominal",
                  "title": "国家",
                  "sort": "-x"
                },
                "tooltip": [
                  {"field": "company_location", "type": "nominal", "title": "国家"},
                  {"field": "mean_salary", "type": "quantitative", "title": "平均年薪 (美元)", "format": ",.0f"}
                ]
              }
            },
            {
              "mark": {
                "type": "text",
                "align": "right",
                "baseline": "middle",
                "dx": -5,
                "color": "white"
              },
              "transform": [
                {
                  "aggregate": [{"op": "mean", "field": "salary_in_usd", "as": "mean_salary"}],
                  "groupby": ["company_location"]
                },
                {
                  "window": [{"op": "rank", "as": "rank"}],
                  "sort": [{"field": "mean_salary", "order": "descending"}]
                },
                {"filter": "datum.rank <= 10"}
              ],
              "encoding": {
                "x": {
                  "field": "mean_salary",
                  "type": "quantitative"
                },
                "y": {
                  "field": "company_location",
                  "type": "nominal",
                  "sort": "-x"
                },
                "text": {"field": "company_location", "type": "nominal"}
              }
            }
          ]
        },
        {
          "width": 400,
          "height": 300,
          "title": "薪资分布对比：美国 vs. 其他国家",
          "mark": {
            "type": "boxplot",
            "extent": "min-max"
          },
          "encoding": {
            "x": {
              "field": "salary_in_usd",
              "type": "quantitative",
              "title": "年薪 (美元)",
              "axis": {"format": "s"}
            },
            "y": {
              "field": "US_vs_ROW",
              "type": "nominal",
              "title": ""
            },
            "color": {"field": "US_vs_ROW", "type": "nominal", "legend": null},
            "tooltip": [
              {"field": "US_vs_ROW", "type": "nominal", "title": "地区"},
              {"field": "salary_in_usd", "type": "quantitative", "aggregate": "mean", "title": "平均年薪", "format": ",.0f"},
              {"field": "salary_in_usd", "type": "quantitative", "aggregate": "median", "title": "年薪中位数", "format": ",.0f"},
              {"field": "salary_in_usd", "type": "quantitative", "aggregate": "max", "title": "最高年薪", "format": ",.0f"}
            ]
          }
        }
      ]
    },
    {
      "hconcat": [
        {
          "width": 400,
          "height": 300,
          "title": "不同经验水平的薪资对比",
          "mark": "bar",
          "encoding": {
            "y": {
              "field": "salary_in_usd",
              "type": "quantitative",
              "aggregate": "mean",
              "title": "平均年薪 (美元)"
            },
            "x": {
              "field": "experience_level_cn",
              "type": "nominal",
              "title": "经验水平",
              "sort": ["入门级", "中级", "高级", "专家级"]
            },
            "color": {
              "field": "US_vs_ROW",
              "type": "nominal",
              "title": "地区",
              "legend": {"orient": "top"}
            },
            "xOffset": {"field": "US_vs_ROW"},
            "tooltip": [
              {"field": "experience_level_cn", "type": "nominal", "title": "经验水平"},
              {"field": "US_vs_ROW", "type": "nominal", "title": "地区"},
              {"field": "salary_in_usd", "type": "quantitative", "aggregate": "mean", "title": "平均年薪", "format": ",.0f"}
            ]
          }
        },
        {
          "width": 400,
          "height": 300,
          "title": "不同公司规模的薪资对比",
          "mark": "bar",
          "encoding": {
            "y": {
              "field": "salary_in_usd",
              "type": "quantitative",
              "aggregate": "mean",
              "title": "平均年薪 (美元)"
            },
            "x": {
              "field": "company_size_cn",
              "type": "nominal",
              "title": "公司规模",
              "sort": ["小型", "中型", "大型"]
            },
            "color": {
                "field": "US_vs_ROW",
                "type": "nominal",
                "title": "地区",
                "legend": {"orient": "top"}
            },
            "xOffset": {"field": "US_vs_ROW"},
            "tooltip": [
              {"field": "company_size_cn", "type": "nominal", "title": "公司规模"},
              {"field": "US_vs_ROW", "type": "nominal", "title": "地区"},
              {"field": "salary_in_usd", "type": "quantitative", "aggregate": "mean", "title": "平均年薪", "format": ",.0f"}
            ]
          }
        }
      ]
    }
  ]
}
